INSERT INTO `msg_email_template` (`id`, `template_code`, `template_name`, `app_code`, `scene_code`, `locale`, `subject_template`, `content_type`, `content_template`, `variable_schema`, `sensitive_variable_names`, `status`, `system_builtin`, `version_no`, `remark`, `create_by`, `create_time`, `update_by`, `update_time`, `deleted`) VALUES (1, 'ADMIN_LOGIN_OTP', '管理系统登录验证码', 'ADMIN', 'LOGIN_OTP', 'zh-CN', '【${systemName}】登录验证码', 'HTML', '<div style=\"margin:0;padding:32px;background:#f4f7fb;font-family:Arial,sans-serif;color:#1f2937;\"><div style=\"max-width:640px;margin:0 auto;background:#ffffff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;\"><div style=\"padding:22px 28px;background:#0f172a;color:#ffffff;\"><div style=\"font-size:13px;opacity:.78;\">${systemName}</div><div style=\"margin-top:4px;font-size:20px;font-weight:700;\">登录验证码</div></div><div style=\"padding:28px;line-height:1.8;font-size:14px;\"><p style=\"margin:0 0 16px;\">您好，${userName}：</p><p style=\"margin:0 0 16px;\">您正在登录 ${systemName}，本次登录验证码为：</p><div style=\"margin:20px 0;padding:20px 24px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px;text-align:center;\"><div style=\"font-size:13px;color:#64748b;\">验证码</div><div style=\"margin-top:6px;font-size:32px;letter-spacing:4px;font-weight:700;color:#0f172a;\">${verifyCode}</div></div><p style=\"margin:0 0 12px;\">验证码有效期为 ${expireMinutes} 分钟，请勿将验证码泄露给他人。</p><p style=\"margin:0;color:#b45309;\">如果本次操作不是您本人发起，请立即联系系统管理员。</p></div><div style=\"padding:16px 28px;background:#f8fafc;color:#64748b;font-size:12px;\">此邮件由 ${systemName} 自动发送，请勿直接回复。</div></div></div>', '{\"userName\": \"张三\", \"systemName\": \"Vexra Admin\", \"verifyCode\": \"123456\", \"expireMinutes\": \"5\"}', '[\"verifyCode\"]', 1, 1, 1, '系统内置模板：管理系统登录验证码', 'system', '2026-07-04 06:40:15.489', 'system', '2026-07-04 07:23:40.914', 0);
INSERT INTO `msg_email_template` (`id`, `template_code`, `template_name`, `app_code`, `scene_code`, `locale`, `subject_template`, `content_type`, `content_template`, `variable_schema`, `sensitive_variable_names`, `status`, `system_builtin`, `version_no`, `remark`, `create_by`, `create_time`, `update_by`, `update_time`, `deleted`) VALUES (2, 'MERCHANT_LOGIN_OTP', '商户系统登录验证码', 'MERCHANT', 'LOGIN_OTP', 'zh-CN', '【${systemName}】登录验证码', 'HTML', '<div style=\"margin:0;padding:32px;background:#f4f7fb;font-family:Arial,sans-serif;color:#1f2937;\"><div style=\"max-width:640px;margin:0 auto;background:#ffffff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;\"><div style=\"padding:22px 28px;background:#0f172a;color:#ffffff;\"><div style=\"font-size:13px;opacity:.78;\">${systemName}</div><div style=\"margin-top:4px;font-size:20px;font-weight:700;\">登录验证码</div></div><div style=\"padding:28px;line-height:1.8;font-size:14px;\"><p style=\"margin:0 0 16px;\">您好，${userName}：</p><p style=\"margin:0 0 16px;\">您正在登录 ${systemName}，本次登录验证码为：</p><div style=\"margin:20px 0;padding:20px 24px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px;text-align:center;\"><div style=\"font-size:13px;color:#64748b;\">验证码</div><div style=\"margin-top:6px;font-size:32px;letter-spacing:4px;font-weight:700;color:#0f172a;\">${verifyCode}</div></div><p style=\"margin:0 0 12px;\">验证码有效期为 ${expireMinutes} 分钟，请勿将验证码泄露给他人。</p><p style=\"margin:0;color:#b45309;\">如非本人操作，请及时修改密码或联系平台客服。</p></div><div style=\"padding:16px 28px;background:#f8fafc;color:#64748b;font-size:12px;\">此邮件由 ${systemName} 自动发送，请勿直接回复。</div></div></div>', '{\"userName\": \"张三\", \"systemName\": \"Vexra Merchant\", \"verifyCode\": \"123456\", \"expireMinutes\": \"5\"}', '[\"verifyCode\"]', 1, 1, 1, '系统内置模板：商户系统登录验证码', 'system', '2026-07-04 06:40:15.489', 'system', '2026-07-04 07:23:40.914', 0);
INSERT INTO `msg_email_template` (`id`, `template_code`, `template_name`, `app_code`, `scene_code`, `locale`, `subject_template`, `content_type`, `content_template`, `variable_schema`, `sensitive_variable_names`, `status`, `system_builtin`, `version_no`, `remark`, `create_by`, `create_time`, `update_by`, `update_time`, `deleted`) VALUES (3, 'ADMIN_PASSWORD_RESET', '管理系统找回密码', 'ADMIN', 'PASSWORD_RESET', 'zh-CN', '【${systemName}】找回密码验证', 'HTML', '<div style=\"margin:0;padding:32px;background:#f4f7fb;font-family:Arial,sans-serif;color:#1f2937;\"><div style=\"max-width:640px;margin:0 auto;background:#ffffff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;\"><div style=\"padding:22px 28px;background:#0f172a;color:#ffffff;\"><div style=\"font-size:13px;opacity:.78;\">${systemName}</div><div style=\"margin-top:4px;font-size:20px;font-weight:700;\">找回密码验证</div></div><div style=\"padding:28px;line-height:1.8;font-size:14px;\"><p style=\"margin:0 0 16px;\">您好，${userName}：</p><p style=\"margin:0 0 16px;\">您正在进行 ${systemName} 找回密码操作。请使用以下验证码完成身份验证：</p><div style=\"margin:20px 0;padding:20px 24px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px;text-align:center;\"><div style=\"font-size:13px;color:#64748b;\">找回密码验证码</div><div style=\"margin-top:6px;font-size:32px;letter-spacing:4px;font-weight:700;color:#0f172a;\">${verifyCode}</div></div><p style=\"margin:0 0 12px;\">验证码有效期为 ${expireMinutes} 分钟，请在有效期内完成密码重置。</p><p style=\"margin:0;color:#b45309;\">如果不是您本人操作，请忽略本邮件并及时联系系统管理员。</p></div><div style=\"padding:16px 28px;background:#f8fafc;color:#64748b;font-size:12px;\">此邮件由 ${systemName} 自动发送，请勿直接回复。</div></div></div>', '{\"userName\": \"张三\", \"resetLink\": \"https://admin.example.com/reset\", \"systemName\": \"Vexra Admin\", \"verifyCode\": \"123456\", \"expireMinutes\": \"5\"}', '[\"verifyCode\", \"resetLink\"]', 1, 1, 1, '系统内置模板：管理系统找回密码', 'system', '2026-07-04 06:40:15.489', 'system', '2026-07-04 07:23:40.914', 0);
