INSERT INTO `msg_email_template` (`id`, `template_code`, `template_name`, `app_code`, `scene_code`, `locale`, `subject_template`, `content_type`, `content_template`, `variable_schema`, `sensitive_variable_names`, `status`, `system_builtin`, `version_no`, `remark`, `create_by`, `create_time`, `update_by`, `update_time`, `deleted`) VALUES (5, 'ADMIN_ACCOUNT_CREATED', '管理系统账号创建通知', 'ADMIN', 'ACCOUNT_CREATED', 'zh-CN', '【${systemName}】账号创建通知', 'HTML', '<div style=\"margin:0;padding:32px;background:#f4f7fb;font-family:Arial,sans-serif;color:#1f2937;\"><div style=\"max-width:640px;margin:0 auto;background:#ffffff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;\"><div style=\"padding:22px 28px;background:#0f172a;color:#ffffff;\"><div style=\"font-size:13px;opacity:.78;\">${systemName}</div><div style=\"margin-top:4px;font-size:20px;font-weight:700;\">账号创建通知</div></div><div style=\"padding:28px;line-height:1.8;font-size:14px;\"><p style=\"margin:0 0 16px;\">您好，${userName}：</p><p style=\"margin:0 0 16px;\">您的 ${systemName} 账号已创建成功。</p><div style=\"margin:20px 0;padding:18px 20px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px;\"><p style=\"margin:0 0 8px;\">登录账号：<strong>${loginAccount}</strong></p><p style=\"margin:0;\">登录地址：<a href=\"${loginUrl}\" style=\"color:#2563eb;text-decoration:none;\">${loginUrl}</a></p></div><p style=\"margin:0 0 12px;\">如系统生成了初始密码，请在首次登录后立即修改密码。</p><p style=\"margin:0;color:#b45309;\">如果您未申请该账号，请联系系统管理员。</p></div><div style=\"padding:16px 28px;background:#f8fafc;color:#64748b;font-size:12px;\">此邮件由 ${systemName} 自动发送，请勿直接回复。</div></div></div>', '{\"loginUrl\": \"https://admin.example.com/login\", \"userName\": \"张三\", \"systemName\": \"Vexra Admin\", \"loginAccount\": \"admin@example.com\", \"initialPassword\": \"******\"}', '[\"initialPassword\"]', 1, 1, 1, '系统内置模板：管理系统账号创建通知', 'system', '2026-07-04 06:40:15.489', 'system', '2026-07-04 07:23:40.914', 0);
INSERT INTO `msg_email_template` (`id`, `template_code`, `template_name`, `app_code`, `scene_code`, `locale`, `subject_template`, `content_type`, `content_template`, `variable_schema`, `sensitive_variable_names`, `status`, `system_builtin`, `version_no`, `remark`, `create_by`, `create_time`, `update_by`, `update_time`, `deleted`) VALUES (6, 'MERCHANT_ACCOUNT_CREATED', '商户系统账号创建通知', 'MERCHANT', 'ACCOUNT_CREATED', 'zh-CN', '【${systemName}】账号创建通知', 'HTML', '<div style=\"margin:0;padding:32px;background:#f4f7fb;font-family:Arial,sans-serif;color:#1f2937;\"><div style=\"max-width:640px;margin:0 auto;background:#ffffff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;\"><div style=\"padding:22px 28px;background:#0f172a;color:#ffffff;\"><div style=\"font-size:13px;opacity:.78;\">${systemName}</div><div style=\"margin-top:4px;font-size:20px;font-weight:700;\">账号创建通知</div></div><div style=\"padding:28px;line-height:1.8;font-size:14px;\"><p style=\"margin:0 0 16px;\">您好，${userName}：</p><p style=\"margin:0 0 16px;\">您的 ${systemName} 账号已创建成功。</p><div style=\"margin:20px 0;padding:18px 20px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px;\"><p style=\"margin:0 0 8px;\">商户名称：<strong>${merchantName}</strong></p><p style=\"margin:0 0 8px;\">登录账号：<strong>${loginAccount}</strong></p><p style=\"margin:0;\">登录地址：<a href=\"${loginUrl}\" style=\"color:#2563eb;text-decoration:none;\">${loginUrl}</a></p></div><p style=\"margin:0;\">请妥善保管账号信息，并在首次登录后及时修改密码。</p></div><div style=\"padding:16px 28px;background:#f8fafc;color:#64748b;font-size:12px;\">此邮件由 ${systemName} 自动发送，请勿直接回复。</div></div></div>', '{\"loginUrl\": \"https://merchant.example.com/login\", \"userName\": \"张三\", \"systemName\": \"Vexra Merchant\", \"loginAccount\": \"merchant@example.com\", \"merchantName\": \"示例商户\", \"initialPassword\": \"******\"}', '[\"initialPassword\"]', 1, 1, 1, '系统内置模板：商户系统账号创建通知', 'system', '2026-07-04 06:40:15.489', 'system', '2026-07-04 07:23:40.914', 0);
INSERT INTO `msg_email_template` (`id`, `template_code`, `template_name`, `app_code`, `scene_code`, `locale`, `subject_template`, `content_type`, `content_template`, `variable_schema`, `sensitive_variable_names`, `status`, `system_builtin`, `version_no`, `remark`, `create_by`, `create_time`, `update_by`, `update_time`, `deleted`) VALUES (7, 'MERCHANT_ONBOARDING_APPROVED', '商户开户审核成功通知', 'MERCHANT', 'MERCHANT_ONBOARDING', 'zh-CN', '【${systemName}】商户开户审核通过', 'HTML', '<div style=\"margin:0;padding:32px;background:#f4f7fb;font-family:Arial,sans-serif;color:#1f2937;\"><div style=\"max-width:640px;margin:0 auto;background:#ffffff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;\"><div style=\"padding:22px 28px;background:#065f46;color:#ffffff;\"><div style=\"font-size:13px;opacity:.78;\">${systemName}</div><div style=\"margin-top:4px;font-size:20px;font-weight:700;\">商户开户审核通过</div></div><div style=\"padding:28px;line-height:1.8;font-size:14px;\"><p style=\"margin:0 0 16px;\">您好，${merchantName}：</p><p style=\"margin:0 0 16px;\">您的商户开户申请已审核通过。</p><div style=\"margin:20px 0;padding:18px 20px;background:#f0fdf4;border:1px solid #bbf7d0;border-radius:8px;\"><p style=\"margin:0 0 8px;\">商户号：<strong>${merchantNo}</strong></p><p style=\"margin:0;\">审核时间：${reviewTime}</p></div><p style=\"margin:0 0 12px;\">您可以登录商户系统查看商户资料、配置 API 密钥并进行后续对接。</p><p style=\"margin:0;\">登录地址：<a href=\"${loginUrl}\" style=\"color:#2563eb;text-decoration:none;\">${loginUrl}</a></p></div><div style=\"padding:16px 28px;background:#f8fafc;color:#64748b;font-size:12px;\">此邮件由 ${systemName} 自动发送，请勿直接回复。</div></div></div>', '{\"loginUrl\": \"https://merchant.example.com/login\", \"merchantNo\": \"M10000001\", \"reviewTime\": \"2026-07-04 10:00:00\", \"systemName\": \"Vexra Merchant\", \"merchantName\": \"示例商户\"}', '[]', 1, 1, 1, '系统内置模板：商户开户审核成功通知', 'system', '2026-07-04 06:40:15.489', 'system', '2026-07-04 07:23:40.914', 0);
INSERT INTO `msg_email_template` (`id`, `template_code`, `template_name`, `app_code`, `scene_code`, `locale`, `subject_template`, `content_type`, `content_template`, `variable_schema`, `sensitive_variable_names`, `status`, `system_builtin`, `version_no`, `remark`, `create_by`, `create_time`, `update_by`, `update_time`, `deleted`) VALUES (8, 'MERCHANT_ONBOARDING_REJECTED', '商户开户审核失败通知', 'MERCHANT', 'MERCHANT_ONBOARDING', 'zh-CN', '【${systemName}】商户开户审核未通过', 'HTML', '<div style=\"margin:0;padding:32px;background:#f4f7fb;font-family:Arial,sans-serif;color:#1f2937;\"><div style=\"max-width:640px;margin:0 auto;background:#ffffff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;\"><div style=\"padding:22px 28px;background:#991b1b;color:#ffffff;\"><div style=\"font-size:13px;opacity:.78;\">${systemName}</div><div style=\"margin-top:4px;font-size:20px;font-weight:700;\">商户开户审核未通过</div></div><div style=\"padding:28px;line-height:1.8;font-size:14px;\"><p style=\"margin:0 0 16px;\">您好，${merchantName}：</p><p style=\"margin:0 0 16px;\">您的商户开户申请暂未通过审核。</p><div style=\"margin:20px 0;padding:18px 20px;background:#fef2f2;border:1px solid #fecaca;border-radius:8px;\"><p style=\"margin:0 0 8px;\">商户号：<strong>${merchantNo}</strong></p><p style=\"margin:0 0 8px;\">审核时间：${reviewTime}</p><p style=\"margin:0;\">未通过原因：${rejectReason}</p></div><p style=\"margin:0;\">请根据提示补充或修改资料后重新提交。</p></div><div style=\"padding:16px 28px;background:#f8fafc;color:#64748b;font-size:12px;\">此邮件由 ${systemName} 自动发送，请勿直接回复。</div></div></div>', '{\"merchantNo\": \"M10000001\", \"reviewTime\": \"2026-07-04 10:00:00\", \"systemName\": \"Vexra Merchant\", \"merchantName\": \"示例商户\", \"rejectReason\": \"资料不完整\"}', '[]', 1, 1, 1, '系统内置模板：商户开户审核失败通知', 'system', '2026-07-04 06:40:15.489', 'system', '2026-07-04 07:23:40.914', 0);
INSERT INTO `msg_email_template` (`id`, `template_code`, `template_name`, `app_code`, `scene_code`, `locale`, `subject_template`, `content_type`, `content_template`, `variable_schema`, `sensitive_variable_names`, `status`, `system_builtin`, `version_no`, `remark`, `create_by`, `create_time`, `update_by`, `update_time`, `deleted`) VALUES (9, 'API_KEY_CREATED', 'API 密钥生成通知', 'MERCHANT', 'API_KEY_CHANGED', 'zh-CN', '【${systemName}】API 密钥生成通知', 'HTML', '<div style=\"margin:0;padding:32px;background:#f4f7fb;font-family:Arial,sans-serif;color:#1f2937;\"><div style=\"max-width:640px;margin:0 auto;background:#ffffff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;\"><div style=\"padding:22px 28px;background:#0f172a;color:#ffffff;\"><div style=\"font-size:13px;opacity:.78;\">${systemName}</div><div style=\"margin-top:4px;font-size:20px;font-weight:700;\">API 密钥生成通知</div></div><div style=\"padding:28px;line-height:1.8;font-size:14px;\"><p style=\"margin:0 0 16px;\">您好，${merchantName}：</p><p style=\"margin:0 0 16px;\">您的商户 API 密钥已生成。</p><div style=\"margin:20px 0;padding:18px 20px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px;\"><p style=\"margin:0 0 8px;\">商户号：<strong>${merchantNo}</strong></p><p style=\"margin:0 0 8px;\">密钥名称：${keyName}</p><p style=\"margin:0 0 8px;\">密钥尾号：<strong>${keyLast4}</strong></p><p style=\"margin:0 0 8px;\">操作人：${operatorName}</p><p style=\"margin:0;\">操作时间：${operationTime}</p></div><p style=\"margin:0;color:#b45309;\">为保障账户安全，邮件中不会展示完整密钥内容。请登录商户系统查看或下载相关密钥信息。</p></div><div style=\"padding:16px 28px;background:#f8fafc;color:#64748b;font-size:12px;\">此邮件由 ${systemName} 自动发送，请勿直接回复。</div></div></div>', '{\"keyName\": \"默认 API 密钥\", \"keyLast4\": \"1234\", \"merchantNo\": \"M10000001\", \"systemName\": \"Vexra Merchant\", \"merchantName\": \"示例商户\", \"operatorName\": \"张三\", \"operationTime\": \"2026-07-04 10:00:00\"}', '[]', 1, 1, 1, '系统内置模板：API 密钥生成通知', 'system', '2026-07-04 06:40:15.489', 'system', '2026-07-04 07:23:40.914', 0);
INSERT INTO `msg_email_template` (`id`, `template_code`, `template_name`, `app_code`, `scene_code`, `locale`, `subject_template`, `content_type`, `content_template`, `variable_schema`, `sensitive_variable_names`, `status`, `system_builtin`, `version_no`, `remark`, `create_by`, `create_time`, `update_by`, `update_time`, `deleted`) VALUES (10, 'API_KEY_RESET', 'API 密钥重置通知', 'MERCHANT', 'API_KEY_CHANGED', 'zh-CN', '【${systemName}】API 密钥重置通知', 'HTML', '<div style=\"margin:0;padding:32px;background:#f4f7fb;font-family:Arial,sans-serif;color:#1f2937;\"><div style=\"max-width:640px;margin:0 auto;background:#ffffff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;\"><div style=\"padding:22px 28px;background:#7c2d12;color:#ffffff;\"><div style=\"font-size:13px;opacity:.78;\">${systemName}</div><div style=\"margin-top:4px;font-size:20px;font-weight:700;\">API 密钥重置通知</div></div><div style=\"padding:28px;line-height:1.8;font-size:14px;\"><p style=\"margin:0 0 16px;\">您好，${merchantName}：</p><p style=\"margin:0 0 16px;\">您的商户 API 密钥已被重置。</p><div style=\"margin:20px 0;padding:18px 20px;background:#fff7ed;border:1px solid #fed7aa;border-radius:8px;\"><p style=\"margin:0 0 8px;\">商户号：<strong>${merchantNo}</strong></p><p style=\"margin:0 0 8px;\">密钥名称：${keyName}</p><p style=\"margin:0 0 8px;\">新密钥尾号：<strong>${keyLast4}</strong></p><p style=\"margin:0 0 8px;\">操作人：${operatorName}</p><p style=\"margin:0;\">操作时间：${operationTime}</p></div><p style=\"margin:0;color:#b45309;\">请确认该操作是否由授权人员发起。如非本人或授权人员操作，请立即联系平台客服。</p></div><div style=\"padding:16px 28px;background:#f8fafc;color:#64748b;font-size:12px;\">此邮件由 ${systemName} 自动发送，请勿直接回复。</div></div></div>', '{\"keyName\": \"默认 API 密钥\", \"keyLast4\": \"5678\", \"merchantNo\": \"M10000001\", \"systemName\": \"Vexra Merchant\", \"merchantName\": \"示例商户\", \"operatorName\": \"张三\", \"operationTime\": \"2026-07-04 10:00:00\"}', '[]', 1, 1, 1, '系统内置模板：API 密钥重置通知', 'system', '2026-07-04 06:40:15.489', 'system', '2026-07-04 07:23:40.914'